SELECT  FROM goods_local_message
WHERE trigger_type IN (0, 1) AND target_system = 0 AND sku IN
#{sku}
AND id IN (
    SELECT MAX(latest.id) FROM goods_local_message latest
    WHERE latest.trigger_type IN (0, 1) AND latest.target_system = 0 AND latest.id < #{beforeId} AND latest.sku IN
    #{sku}
    GROUP BY latest.sku
)
